// Generated bitmap font data (Tahoma, 1bpp). Glyphs 32..255. Format per glyph: width byte, then height rows of ceil(width/8) bytes.
namespace J2ME
{
    static class FontData
    {
        public static readonly int[] PixelSizes = { 11, 13, 15, 17, 20, 24 };
        public static readonly FontEntry[] Fonts =
        {
            new FontEntry(11, false, 14, 11, ""),
            new FontEntry(13, false, 16, 13, ""),
            new FontEntry(15, false, 19, 15, ""),
            new FontEntry(17, false, 21, 17, ""),
            new FontEntry(20, false, 25, 20, ""),
            new FontEntry(24, false, 29, 24, ""),
            new FontEntry(11, true, 14, 11, ""),
            new FontEntry(13, true, 16, 13, ""),
            new FontEntry(15, true, 19, 15, ""),
            new FontEntry(17, true, 21, 17, ""),
            new FontEntry(20, true, 25, 20, ""),
            new FontEntry(24, true, 29, 24, ""),
        };
    }

    sealed class FontEntry
    {
        public readonly int PixelSize, Height, Ascent;
        public readonly bool Bold;
        public readonly string Data;
        public FontEntry(int pixelSize, bool bold, int height, int ascent, string data) { PixelSize = pixelSize; Bold = bold; Height = height; Ascent = ascent; Data = data; }
    }
}
